#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <cmath>
#include <string>

static void check_bf16_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kBFloat16,
        name, " must have bfloat16 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Host-side inverse normal CDF (Abramowitz-Stegun rational
// approximation, formula 26.2.23). Mirrors the reference's
// _ndtri implementation exactly so that the kernel-side
// z_multiplier matches the PyTorch reference's per-row cutoff
// derivation.
static double host_ndtri(double p) {
    constexpr double a1 = -3.969683028665376e+01;
    constexpr double a2 =  2.209460984245205e+02;
    constexpr double a3 = -2.759285104469687e+02;
    constexpr double a4 =  1.383577518672690e+02;
    constexpr double a5 = -3.066479806614716e+01;
    constexpr double a6 =  2.506628277459239e+00;
    constexpr double b1 = -5.447609879822406e+01;
    constexpr double b2 =  1.615858368580409e+02;
    constexpr double b3 = -1.556989798598866e+02;
    constexpr double b4 =  6.680131188771972e+01;
    constexpr double b5 = -1.328068155288572e+01;
    constexpr double c1 = -7.784894002430293e-03;
    constexpr double c2 = -3.223964580411365e-01;
    constexpr double c3 = -2.400758277161838e+00;
    constexpr double c4 = -2.549732539343734e+00;
    constexpr double c5 =  4.374664141464968e+00;
    constexpr double c6 =  2.938163982698783e+00;
    constexpr double d1 =  7.784695709041462e-03;
    constexpr double d2 =  3.224671290700398e-01;
    constexpr double d3 =  2.445134137142996e+00;
    constexpr double d4 =  3.754408661907416e+00;
    constexpr double p_low = 0.02425;
    constexpr double p_high = 1.0 - p_low;

    if (p < p_low) {
        const double q = std::sqrt(-2.0 * std::log(p));
        return (((((c1*q + c2)*q + c3)*q + c4)*q + c5)*q + c6) /
               ((((d1*q + d2)*q + d3)*q + d4)*q + 1.0);
    } else if (p <= p_high) {
        const double q = p - 0.5;
        const double r = q * q;
        return (((((a1*r + a2)*r + a3)*r + a4)*r + a5)*r + a6) * q /
               (((((b1*r + b2)*r + b3)*r + b4)*r + b5)*r + 1.0);
    } else {
        const double q = std::sqrt(-2.0 * std::log(1.0 - p));
        return -(((((c1*q + c2)*q + c3)*q + c4)*q + c5)*q + c6) /
                ((((d1*q + d2)*q + d3)*q + d4)*q + 1.0);
    }
}

// Destination-passing-style entry. Per definition.json:
//   inputs          : [batch_size, seq_len, intermediate_size] bf16
//   target_sparsity : scalar fp32 in [0, 1]; 0.0 returns inputs unchanged
//   output          : [batch_size, seq_len, intermediate_size] bf16 (DPS)
//
// intermediate_size is workload-variable (4096, 8192, 12288, 16384).
void run(
    const torch::Tensor& inputs,
    double target_sparsity,
    torch::Tensor output
) {
    TORCH_CHECK(inputs.dim() == 3, "inputs must be 3D [B, S, I]");
    TORCH_CHECK(output.dim() == 3, "output must be 3D [B, S, I]");
    TORCH_CHECK(output.sizes() == inputs.sizes(),
                "output shape must match inputs");
    TORCH_CHECK(inputs.size(2) % 2 == 0,
                "intermediate_size must be even for BF16x2 vector access, got ",
                inputs.size(2));

    check_bf16_contiguous_cuda(inputs, "inputs");
    check_bf16_contiguous_cuda(output, "output");

    // Early return: target_sparsity == 0.0 means no sparsity; the
    // reference returns inputs unchanged. DPS contract requires the
    // output tensor to be written, so copy inputs -> output in-place.
    if (target_sparsity == 0.0) {
        output.copy_(inputs);
        return;
    }

    // Host-side ndtri evaluation (one-shot per kernel invocation).
    const float z_multiplier =
        static_cast<float>(host_ndtri(target_sparsity));

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_053_gaussian_topk_sparse_activation_launcher(
        inputs, z_multiplier, output, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "BF16 Gaussian top-k sparse activation: per-row mean/std + "
        "host-side ndtri(target_sparsity) + ReLU(x - cutoff). Single "
        "DPS output. intermediate_size workload-variable.");
}

#include "kernel.h"
#include <cuda_bf16.h>
#include <cuda_runtime.h>

// BF16 Gaussian top-k sparse activation.
//
// Per (b, s) row of intermediate_size BF16 elements:
//   Pass 1 (reduction): each thread stride-loops over the row,
//     reads BF16x2 pairs, casts to fp32, accumulates partial sum
//     and partial sum-of-squares. Warp-shuffle reduces within each
//     warp; 8-way cross-warp reduction via shared memory. Thread 0
//     computes mean = sum/N, var = sum_sq/N - mean^2,
//     std = sqrt(max(var, 0)), cutoff = mean + std * z_multiplier,
//     and broadcasts `cutoff` through a shared float.
//   Pass 2 (output): each thread stride-loops again, reads BF16x2
//     pairs as fp32, computes max(x - cutoff, 0.0f), casts back
//     to BF16 and stores as BF16x2 pairs.
//
// One CTA per (b, s) row. Grid: (batch_size * seq_len,).
// BLOCK_THREADS = 256 (8 warps).
//
// intermediate_size is workload-variable (4096, 8192, 12288,
// 16384 in the workload sweep). The kernel handles any even
// intermediate_size via BF16x2 strides.

namespace {

constexpr int kBlockThreads = 256;
constexpr int kWarpSize = 32;
constexpr int kNumWarps = kBlockThreads / kWarpSize;  // 8

__global__ void __launch_bounds__(kBlockThreads, 4)
problem_053_gaussian_topk_sparse_kernel(
    const __nv_bfloat16* __restrict__ inputs,
    __nv_bfloat16* __restrict__ output,
    int intermediate_size,
    float z_multiplier) {

    const int row = blockIdx.x;
    const int tid = threadIdx.x;
    const int row_offset = row * intermediate_size;

    // BF16x2 view over the row. intermediate_size is even (every
    // workload uses a power-of-two times something divisible by 2).
    const __nv_bfloat162* in_row_vec =
        reinterpret_cast<const __nv_bfloat162*>(inputs + row_offset);
    __nv_bfloat162* out_row_vec =
        reinterpret_cast<__nv_bfloat162*>(output + row_offset);
    const int row_pairs = intermediate_size >> 1;

    // Pass 1: partial sum + partial sum-of-squares in fp32.
    float thread_sum = 0.0f;
    float thread_sum_sq = 0.0f;
    for (int i = tid; i < row_pairs; i += kBlockThreads) {
        const __nv_bfloat162 v_pair = __ldg(in_row_vec + i);
        const float2 v_f2 = __bfloat1622float2(v_pair);
        thread_sum    += v_f2.x + v_f2.y;
        thread_sum_sq += v_f2.x * v_f2.x + v_f2.y * v_f2.y;
    }

    // Warp-shuffle reduction.
    #pragma unroll
    for (int off = kWarpSize / 2; off > 0; off >>= 1) {
        thread_sum    += __shfl_xor_sync(0xffffffff, thread_sum, off);
        thread_sum_sq += __shfl_xor_sync(0xffffffff, thread_sum_sq, off);
    }

    // Cross-warp reduction via shared memory.
    __shared__ float warp_sums[kNumWarps];
    __shared__ float warp_sum_sqs[kNumWarps];
    const int warp_id = tid / kWarpSize;
    const int lane_id = tid % kWarpSize;
    if (lane_id == 0) {
        warp_sums[warp_id] = thread_sum;
        warp_sum_sqs[warp_id] = thread_sum_sq;
    }
    __syncthreads();

    __shared__ float row_cutoff;
    if (tid == 0) {
        float total_sum = 0.0f;
        float total_sum_sq = 0.0f;
        #pragma unroll
        for (int w = 0; w < kNumWarps; ++w) {
            total_sum    += warp_sums[w];
            total_sum_sq += warp_sum_sqs[w];
        }
        const float n_f = static_cast<float>(intermediate_size);
        const float mean = total_sum / n_f;
        const float var = fmaxf(total_sum_sq / n_f - mean * mean, 0.0f);
        const float std_val = sqrtf(var);
        row_cutoff = mean + std_val * z_multiplier;
    }
    __syncthreads();

    const float cutoff = row_cutoff;

    // Pass 2: per-element max(x - cutoff, 0) in fp32; cast back to BF16.
    for (int i = tid; i < row_pairs; i += kBlockThreads) {
        const __nv_bfloat162 v_pair = __ldg(in_row_vec + i);
        const float2 v_f2 = __bfloat1622float2(v_pair);
        const float y0 = fmaxf(v_f2.x - cutoff, 0.0f);
        const float y1 = fmaxf(v_f2.y - cutoff, 0.0f);
        out_row_vec[i] = __float22bfloat162_rn(make_float2(y0, y1));
    }
}

}  // namespace

void problem_053_gaussian_topk_sparse_activation_launcher(
    const torch::Tensor& inputs,
    float z_multiplier,
    torch::Tensor& output,
    cudaStream_t stream) {

    // inputs is [B, S, intermediate_size] BF16.
    const int64_t batch_size = inputs.size(0);
    const int64_t seq_len = inputs.size(1);
    const int64_t intermediate_size = inputs.size(2);
    const int rows = static_cast<int>(batch_size * seq_len);
    const int int_sz = static_cast<int>(intermediate_size);

    dim3 grid(rows);
    dim3 block(kBlockThreads);

    problem_053_gaussian_topk_sparse_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const __nv_bfloat16*>(inputs.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(output.data_ptr<at::BFloat16>()),
        int_sz,
        z_multiplier);
}

#pragma once

#ifndef PROBLEM_053_GAUSSIAN_TOPK_SPARSE_ACTIVATION_KERNEL_H
#define PROBLEM_053_GAUSSIAN_TOPK_SPARSE_ACTIVATION_KERNEL_H

#include <cuda_runtime.h>
#include <torch/extension.h>

// Host launcher for the BF16 Gaussian top-k sparse activation kernel.
//
// For each (b, s) row of BF16 inputs[b, s, :] of length
// intermediate_size, compute in fp32:
//   mean   = mean_i(inputs[b, s, i])
//   var    = mean_i(inputs[b, s, i]^2) - mean^2
//   std    = sqrt(max(var, 0))
//   cutoff = mean + std * z_multiplier
// where `z_multiplier = ndtri(target_sparsity)` is precomputed
// ONCE on the host before the launch (Abramowitz-Stegun rational
// approximation, formula 26.2.23 from the reference's ndtri
// implementation; `target_sparsity` is a kernel-invocation constant
// scalar input). The output is the per-element fused
// `max(input.fp32 - cutoff, 0.0f)` cast back to BF16.
//
// One CTA per (b, s) row over the row's full intermediate_size
// elements via stride-loop. BF16x2 vector loads/stores in pass 2.
void problem_053_gaussian_topk_sparse_activation_launcher(
    const torch::Tensor& inputs,
    float z_multiplier,
    torch::Tensor& output,
    cudaStream_t stream);

#endif  // PROBLEM_053_GAUSSIAN_TOPK_SPARSE_ACTIVATION_KERNEL_H
